func (this *LRUCache) Get(key int) int {
    for i := range this.cache {
        if this.cache[i][0] == key {
            tmp := this.cache[i]
            this.cache = append(this.cache[:i], this.cache[i+1:]...)
            this.cache = append(this.cache, tmp)
            return tmp[1]
        }
    }
    return -1
}

func (this *LRUCache) Put(key int, value int) {
