            this.cache = append(this.cache[:i], this.cache[i+1:]...)
            tmp[1] = value
            this.cache = append(this.cache, tmp)
            return
        }
    }

    if len(this.cache) == this.capacity {
        this.cache = this.cache[1:]
    }

    this.cache = append(this.cache, [2]int{key, value})
